// Varredura de instrucoes direcionadas a IA escondidas no texto principal do documento
function scanTextForInjection(sourceText) {
  if (!sourceText) return [];
  const patterns = [
    /aten[cç][aã]o\s+(intelig[eê]ncia\s+artificial|ia|ai)\b[^.\n]*[.\n]?/gi,
    /\b(ignor[ea]|desconsider[ea])\s+(as\s+|todas\s+as\s+)?(instru[cç][oõ]es|comandos)\s+(anteriores|acima)[^.\n]*[.\n]?/gi,
    /\bvoc[eê]\s+[eé]\s+(um[a]?\s+)?(modelo\s+de\s+linguagem|assistente\s+de\s+ia|llm|chatgpt|gpt)\b[^.\n]*[.\n]?/gi,
    /\b(system\s*prompt|prompt\s+injection)\b[^.\n]*[.\n]?/gi,
    /\bai\s+attention\b[^.\n]*[.\n]?/gi,
    /\bdear\s+(ai|assistant|language\s+model)\b[^.\n]*[.\n]?/gi,
  ];

  const matches = new Set();
  for (const rx of patterns) {
    let m;
    while ((m = rx.exec(sourceText)) !== null) {
      matches.add(m[0].trim());
      if (m.index === rx.lastIndex) rx.lastIndex++;
    }
  }
  return [...matches];
}

