// Decodifica sequencias de caracteres na faixa de Unicode Tags (U+E0000-U+E007F) --
// esteganografia usada em prompt injection real contra LLMs: cada caractere ASCII
// do payload e deslocado para essa faixa (codigo alvo = 0xE0000 + codigo ASCII).
// Nenhuma fonte comum tem glifo desenhado ali, entao o texto nao aparece na tela
// nem na impressao -- mas continua presente, caractere por caractere, em
// qualquer extracao de texto Unicode-aware. E invisibilidade "de fabrica": nao
// depende de cor, tamanho ou modo de renderizacao, por isso a checagem roda
// sobre o texto ja recuperado por Detect Hidden Text (que ve o que a extracao
// padrao do PDF descarta), nao sobre fullText.
function decodeUnicodeTagRuns(sourceText) {
  if (!sourceText) return [];
  const runs = [];
  const rx = /[\u{E0000}-\u{E007F}]+/gu;
  let m;
  while ((m = rx.exec(sourceText)) !== null) {
    const decoded = [...m[0]]
      .map((ch) => ch.codePointAt(0))
      .filter((cp) => cp >= 0xE0020 && cp <= 0xE007E)
      .map((cp) => String.fromCharCode(cp - 0xE0000))
      .join('');
    if (decoded.trim()) runs.push(decoded);
  }
  return runs;
}

// Contraparte de decodeUnicodeTagRuns para uma string inteira: as tags voltam
// ao ASCII e o resto do texto passa intacto. Sem isto, todo trecho citado entre
// aspas num achado sai vazio -- os caracteres estao la, mas nenhuma fonte comum
// os desenha, entao o laudo anunciava a fraude sem conseguir mostra-la.
function revelarTagsUnicode(sourceText) {
  if (!sourceText) return '';
  return [...sourceText]
    .map((ch) => {
      const cp = ch.codePointAt(0);
      if (cp >= 0xE0020 && cp <= 0xE007E) return String.fromCharCode(cp - 0xE0000);
      if (cp >= 0xE0000 && cp <= 0xE007F) return ''; // tags de controle, sem equivalente legivel
      return ch;
    })
    .join('');
}

